"""Generated by the QA agent for STORY-003: Transfer money between accounts."""


def test_tc_003_01_valid_transfer_moves_money(api):
    """TC-003-01"""
    a = api.create_account("Sara", 500)
    b = api.create_account("Youssef", 100)
    r = api.post("/transfers", json={"from_account": a["id"], "to_account": b["id"], "amount": 200})
    assert r.status_code == 201, r.text
    assert r.json()["id"].startswith("TRF-")
    assert r.json()["status"] == "completed"
    assert api.balance(a["id"]) == 300
    assert api.balance(b["id"]) == 300


def test_tc_003_02_transfer_above_balance_refused(api):
    """TC-003-02"""
    a = api.create_account("Sara", 50)
    b = api.create_account("Youssef", 0)
    r = api.post("/transfers", json={"from_account": a["id"], "to_account": b["id"], "amount": 100})
    assert r.status_code == 409, f"expected 409, got {r.status_code}: {r.text}"
    assert api.balance(a["id"]) == 50
    assert api.balance(b["id"]) == 0


def test_tc_003_03_same_account_rejected(api):
    """TC-003-03"""
    a = api.create_account("Sara", 100)
    r = api.post("/transfers", json={"from_account": a["id"], "to_account": a["id"], "amount": 10})
    assert r.status_code == 422, r.text


def test_tc_003_04_unknown_destination_404(api):
    """TC-003-04"""
    a = api.create_account("Sara", 100)
    r = api.post("/transfers", json={"from_account": a["id"], "to_account": "ACC-9999", "amount": 10})
    assert r.status_code == 404, r.text
    assert api.balance(a["id"]) == 100


def test_tc_003_05_negative_amount_rejected(api):
    """TC-003-05"""
    a = api.create_account("Sara", 100)
    b = api.create_account("Youssef", 0)
    r = api.post("/transfers", json={"from_account": a["id"], "to_account": b["id"], "amount": -10})
    assert r.status_code == 422, r.text
